// Inline practice and post-submission transcript comparison.
let typeFilter='全部',reviewPart=0,reviewMode='compare',activeResult=null,showOriginal=false;
const baseGrade=grade; const legacySave=save; window.removeEventListener('beforeunload',legacySave);
grade=function(t,answers){const rows=baseGrade(t,answers);t.parts.flatMap(p=>p.questions).forEach((q,i)=>{if(!q.components)return;let candidates=[''];for(const choices of q.components)candidates=candidates.flatMap(a=>choices.map(b=>a+' '+b));const norm=s=>normalize(s).replace(/\band\b/g,' ').replace(/[,+/&]/g,' ').split(/\s+/).filter(Boolean).sort().join(' ');rows[i].correct=!!rows[i].yours.trim()&&candidates.some(c=>norm(c)===norm(rows[i].yours));rows[i].answer=q.answer});return rows};
function partState(t,pi){let h=history.find(h=>h.testId===t.id&&(h.scope==='part'?h.partIndex===pi:true));if(h)return '已完成';return read('session-'+t.id+'-part-'+pi,null)?'练习中':'未开始'}
home=function(){view='home';let books=[...new Set(library.map(t=>t.book))].sort((a,b)=>b-a);let tests=allTests().filter(t=>t.type===subject&&(book==='all'||String(t.book)===book)&&(!search||t.title.toLowerCase().includes(search.toLowerCase())));app.innerHTML=header()+`<main class="catalog"><div class="breadcrumb">首页 <span>› ${subject==='listening'?'听力':'阅读'}剑雅真题</span></div><div class="catalog-layout"><section><div class="catalog-filters"><div class="filter-row"><b>科目</b><button data-subject="listening" class="filter-pill ${subject==='listening'?'selected':''}">听力 Listening</button><button data-subject="reading" class="filter-pill ${subject==='reading'?'selected':''}">阅读 Reading</button><span class="filter-spacer"></span><input class="search-box" id="search" placeholder="搜索试卷" value="${escapeHTML(search)}"></div><div class="filter-row"><b>册数</b><button class="filter-pill ${book==='all'?'selected':''}" data-book="all">全部</button>${books.map(b=>`<button class="filter-pill ${book===String(b)?'selected':''}" data-book="${b}">剑雅 ${b}</button>`).join('')}</div><div class="filter-row"><b>题型</b>${['全部','填空','选择','配对','图表'].map(v=>`<button class="filter-pill ${typeFilter===v?'selected':''}" data-filter="${v}">${v}</button>`).join('')}<span class="filter-spacer"></span><button data-mode="practice" class="filter-pill ${mode==='practice'?'selected':''}">自由练习</button><button data-mode="exam" class="filter-pill ${mode==='exam'?'selected':''}">限时模考</button></div></div><div class="status-legend"><span>◉ 未开始</span><span class="working">◷ 练习中</span><span class="completed">✓ 已完成</span></div><details class="audio-help"><summary>音频在哪里添加？</summary><p>每个 Part 下方都有“＋ Part X 音频”，点击选择该部分的录音。进入题目后，顶部也能选择或更换音频。</p><p>剑雅 18、19 已内置在线音频，手机和电脑均可直接播放。自行选择的替换录音与作答仅保存在当前浏览器。</p></details>${books.filter(b=>tests.some(t=>t.book===b)).map(b=>`<section class="book-row"><div class="book-banner"><div><h2>${subject==='listening'?'LISTENING':'READING'}</h2><span>ACADEMIC <strong>${b}</strong></span></div></div><div class="test-columns">${tests.filter(t=>t.book===b).map(t=>`<article class="test-column"><div class="test-column-title"><b>Test ${t.testNumber}</b><button class="whole-paper" data-whole="${t.id}">整套练习 ↗</button></div>${t.parts.map((p,i)=>{let visible=typeFilter==='全部'||p.questionTypes?.some(v=>v.includes(typeFilter));let status=partState(t,i);return `<button class="part-entry ${!visible?'filter-hidden':''}" data-test="${t.id}" data-pi="${i}"><span class="entry-icon ${status==='已完成'?'done':status==='练习中'?'working':''}">${status==='已完成'?'✓':'▷'}</span><span><b>${subject==='listening'?'Part':'Passage'} ${i+1}</b> <span class="part-types">${escapeHTML((p.questionTypes||['填空 / 选择']).join('　'))}</span><small>${status}</small></span></button>`}).join('')}</article>`).join('')}</div></section>`).join('')}${tests.some(t=>!t.book)?`<section class="card"><h3>我的导入试卷</h3>${tests.filter(t=>!t.book).map(t=>`<button class="secondary" data-whole="${t.id}">${escapeHTML(t.title)}</button>`).join('')}</section>`:''}${!tests.length?'<div class="empty">未找到试卷</div>':''}</section><aside class="catalog-side"><section class="side-panel"><h3>我的雅思练习室</h3><p>在题目空格直接作答，交卷后核对答案，并查看听力原文。</p><div class="mini-stat"><strong>${history.length}</strong><span>次练习记录</span></div><button class="outline-action" id="history-side">查看我的练习记录 →</button></section><section class="side-panel"><h3>练习小贴士</h3><p>填空题：在原题空格中输入答案。</p><p>选择题：在题目旁选择选项字母。</p><p>听力原文在交卷后的复盘页展示；可与批阅结果并排对照。</p><p>剑雅 18、19 可直接播放在线音频；其他册可分别为每个 Part 选择本地录音。</p></section><section class="side-panel"><h3>素材状态</h3><p>已整理剑雅 ${books.slice().reverse().join("、")}，共 ${library.length} 套试卷。</p><p class="muted">题目与听力原文已提取为网页文字；扫描件仍可能存在识别错字，可通过原题对照核实。</p><button class="text-action" id="report">查看导入报告 ↗</button><button class="outline-action" id="import-side">＋ 导入题库 JSON</button></section></aside></div></main><footer>IELTS LAB · 听力 / 阅读练习室　｜　作答保存在当前浏览器</footer>`;bindHeader();document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;home()});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{book=b.dataset.book;home()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{typeFilter=b.dataset.filter;home()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;home()});document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>start(allTests().find(t=>t.id===b.dataset.test),{part:+b.dataset.pi}));document.querySelectorAll('[data-whole]').forEach(b=>b.onclick=()=>start(allTests().find(t=>t.id===b.dataset.whole)));$('#search').onchange=e=>{search=e.target.value;home()};$('#history-side').onclick=showHistory;$('#import-side').onclick=()=>$('#import-file').click();$('#report').onclick=()=>window.open('import-report.html','_blank')};
function sessionKey(){return 'session-'+session.testId+(session.scope==='part'?'-part-'+session.entryPart:'')}
save=function(){if(!session||view!=='exam')return;store(sessionKey(),{...session,remaining:remaining()})};
function questionRange(){const t=test();let begin=session.scope==='part'?offset(session.entryPart):0,total=session.scope==='part'?t.parts[session.entryPart].questions.length:t.parts.flatMap(p=>p.questions).length;return {begin,total,numbers:Array.from({length:total},(_,i)=>begin+i+1)}}
start=function(t,options={}){if(!t)return;stop();audio?.pause();let scope=Number.isInteger(options.part)?'part':'test',pi=options.part??0,key='session-'+t.id+(scope==='part'?'-part-'+pi:''),old=read(key,null),duration=scope==='part'?(t.type==='listening'?10:20):t.duration;session=old?.testId===t.id?old:{testId:t.id,scope,entryPart:pi,answers:{},flags:{},remaining:duration*60,mode,deadline:Date.now()+duration*60000,paused:false};partIndex=pi;showOriginal=false;sourceView='inline';view='exam';renderExam();clock=setInterval(()=>{if(view!=='exam'||session.paused)return;if(session.mode==='practice')session.remaining=Math.max(0,session.remaining-1);$('#timer').textContent=time(remaining());save();if(!remaining()&&session.mode==='exam')finish(true)},1000);if(!remaining()&&session.mode==='exam')finish(true)};
function answerControl(q,n,{review=false,row=null}={}){let val=review?(row?.yours||''):(session.answers[n]||''),status=review?(row?.correct===true?'is-right':row?.correct===false?'is-wrong':'is-pending'):'',disabled=review||session.paused?'disabled':'',klass='inline-answer '+status;let field='';let answer=q.answer,letterOnly=typeof answer==='string'&&/^[A-J]$/.test(answer),bool=['TRUE','FALSE','NOT GIVEN'].includes(answer),yesno=['YES','NO'].includes(answer);if(bool||yesno||letterOnly){let opts=bool?['TRUE','FALSE','NOT GIVEN']:yesno?['YES','NO','NOT GIVEN']:(q.allowedOptions||Array.from({length:10},(_,i)=>String.fromCharCode(65+i)));field=`<select class="${klass}" aria-label="第${n}题答案" data-answer="${n}" id="answer-${n}" ${disabled}><option value="">${n}</option>${opts.map(o=>`<option ${normalize(val)===normalize(o)?'selected':''} value="${o}">${o}</option>`).join('')}</select>`}else field=`<input class="${klass}" aria-label="第${n}题答案" data-answer="${n}" id="answer-${n}" value="${escapeHTML(val)}" placeholder="${n}" autocomplete="off" ${disabled}>`;return `<span class="inline-field ${status}" data-q="${n}">${field}${review?`<span class="inline-verdict">${row?.correct===true?'✓':row?.correct===false?'✗':'待核对'}</span>${row?.correct!==true?`<small class="expected-answer">${row?.answer?escapeHTML(row.answer):'源答案未确认'}</small>`:''}`:`<button class="inline-flag ${session.flags[n]?'on':''}" data-flag="${n}" aria-label="标记第${n}题" title="标记待检查">⚑</button>`}</span>`}
function nativePart(t,pi,review=false,rows=[]){let p=t.parts[pi],off=t.parts.slice(0,pi).reduce((n,p)=>n+p.questions.length,0);if(!p.nativeHtml)return `<div class="native-task">${p.questions.map((q,i)=>`<p>${escapeHTML(q.prompt)} ${answerControl(q,off+i+1,{review,row:rows.find(r=>r.n===off+i+1)})}</p>`).join('')}</div>`;let markup=p.nativeHtml.replace(/\{\{q:(\d+)\}\}/g,(_,s)=>{let n=+s,q=p.questions.find(q=>q.sourceNumber===n);return q?answerControl(q,n,{review,row:rows.find(r=>r.n===n)}):''});return `<div class="native-task ${largeText?'large':''}">${p.hasDiagram?`<details class="diagram-reference" open><summary>题目图表 / 地图</summary>${(p.sourceImages||[]).map(u=>`<img src="${escapeHTML(u)}" alt="原题图表" loading="lazy">`).join('')}</details>`:''}${markup}</div>`}
renderExam=function(){let t=test(),p=t.parts[partIndex],range=questionRange(),list=t.type==='listening',off=offset(partIndex);app.innerHTML=`<header class="paper-header"><button class="paper-brand" id="paper-home">i. <span>IELTS LAB</span></button><div class="paper-title"><b>【${list?'听力':'阅读'}】C${t.book||''} Test ${t.testNumber||''} ${list?'Part':'Passage'} ${partIndex+1}</b><small><span id="timer">${time(remaining())}</span>　${session.mode==='exam'?'限时模考':'自由练习'}</small></div>${list?'<div id="audio-mount" class="header-audio"></div>':''}<div class="paper-actions">${list?'<label class="audio-select">选择音频<input type="file" id="audio-file" accept="audio/*"></label>':''}${session.mode==='practice'?`<button id="pause">${session.paused?'继续':'暂停'}</button>`:''}<button id="submit">交卷</button><button id="exit">保存退出</button></div></header><div class="paper-tools"><b>Questions ${off+1}–${off+p.questions.length}</b><span id="save-status">自动保存已开启</span><div class="filter-spacer"></div><button id="font">Aa 字号</button><button id="original-toggle">${showOriginal?'返回作答':'原题对照'}</button></div>${session.paused?'<div class="paper-paused"><b>练习已暂停</b><p>点击顶部“继续”恢复作答</p></div>':''}<div class="paper-content ${list?'listening-paper':'reading-paper'} ${session.paused?'paused-content':''}">${!list?`<article class="reading-pane"><h2>${escapeHTML(p.title)}</h2>${p.readingHtml||`<div class="extracted-text">${escapeHTML(p.passage||'')}</div>`}<details><summary>查看原题完整页面</summary>${(p.sourceImages||[]).map(u=>`<img class="original-page" src="${escapeHTML(u)}" loading="lazy" alt="阅读原题">`).join('')}${p.sourceHtml||''}</details></article>`:''}<article class="task-pane">${showOriginal?`<div class="original-comparison"><p class="muted">原题仅用于核对内容，点击“返回作答”在空格中输入答案。</p>${(p.sourceImages||[]).map(u=>`<img class="original-page" src="${escapeHTML(u)}" alt="原题页面" loading="lazy">`).join('')}${p.sourceHtml||''}</div>`:nativePart(t,partIndex)}</article></div><footer class="paper-footer"><div class="footer-parts">${t.parts.map((p,i)=>session.scope==='part'&&i!==session.entryPart?'':`<button data-part="${i}" class="${i===partIndex?'active':''}">${list?'Part':'Passage'} ${i+1}</button>`).join('')}</div><div class="paper-qnav">${range.numbers.map(n=>`<button data-jump="${n}" aria-label="跳转第${n}题" class="${session.answers[n]?.trim()?'answered':''} ${session.flags[n]?'flagged':''}">${n}</button>`).join('')}</div><span id="progress">${range.numbers.filter(n=>session.answers[n]?.trim()).length}/${range.total} 已答</span><div class="paper-arrows"><button id="prev" ${partIndex===0||session.scope==='part'?'disabled':''}>←</button><button id="next" ${partIndex===t.parts.length-1||session.scope==='part'?'disabled':''}>→</button></div></footer>`;
$('#paper-home').onclick=exit;$('#exit').onclick=exit;$('#submit').onclick=submitDialog;$('#pause')?.addEventListener('click',()=>{session.paused=!session.paused;if(session.paused)audio?.pause();save();renderExam()});$('#font').onclick=()=>{largeText=!largeText;renderExam()};$('#original-toggle').onclick=()=>{showOriginal=!showOriginal;renderExam()};document.querySelectorAll('[data-answer]').forEach(e=>e.addEventListener(e.tagName==='SELECT'?'change':'input',()=>{session.answers[e.dataset.answer]=e.value;save();$(`[data-jump="${e.dataset.answer}"]`)?.classList.toggle('answered',!!e.value.trim());$('#progress').textContent=range.numbers.filter(n=>session.answers[n]?.trim()).length+'/'+range.total+' 已答';$('#save-status').textContent='✓ 已保存'}));document.querySelectorAll('[data-flag]').forEach(b=>b.onclick=()=>{let n=b.dataset.flag;session.flags[n]=!session.flags[n];b.classList.toggle('on',session.flags[n]);$(`[data-jump="${n}"]`)?.classList.toggle('flagged',session.flags[n]);save()});document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{partIndex=+b.dataset.part;showOriginal=false;renderExam()});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>jump(+b.dataset.jump));$('#prev').onclick=()=>{partIndex--;showOriginal=false;renderExam()};$('#next').onclick=()=>{partIndex++;showOriginal=false;renderExam()};if(list){if(audio)$('#audio-mount').append(audio);else $('#audio-mount').innerHTML='<span class="muted">♬ 请加载本地对应录音</span>';$('#audio-file').onchange=e=>{let f=e.target.files[0];if(!f)return;audio?.pause();if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(f);audioName=f.name;audio=document.createElement('audio');audio.controls=true;audio.src=audioURL;audio.setAttribute('aria-label','听力录音');audio.onerror=()=>toast('录音无法播放，请检查文件格式');renderExam();toast('已加载：'+f.name)}}};
function jump(n){let t=test(),pi=t.parts.findIndex((p,i)=>n>offset(i)&&n<=offset(i)+p.questions.length);if(pi!==partIndex||showOriginal){partIndex=pi;showOriginal=false;renderExam()}let e=$('#answer-'+n);e?.scrollIntoView({block:'center',behavior:'smooth'});e?.focus({preventScroll:true})}
submitDialog=function(){let range=questionRange(),filled=range.numbers.filter(n=>session.answers[n]?.trim()).length,d=document.createElement('dialog');d.className='submit-dialog';d.innerHTML=`<h2>确认交卷？</h2><p>已作答 ${filled}/${range.total} 题${filled<range.total?`，剩余 ${range.total-filled} 题未答`:''}。</p><p class="muted">交卷后自动核对答案，听力可查看原文对照。</p><div class="dialog-actions"><button class="secondary" id="cancel-submit">继续作答</button><button class="primary" id="confirm-submit">确认交卷</button></div>`;document.body.append(d);d.showModal();d.querySelector('#cancel-submit').onclick=()=>d.remove();d.querySelector('#confirm-submit').onclick=()=>{d.remove();finish(false)}};
finish=function(auto){stop();audio?.pause();let t=test(),range=questionRange(),rows=grade(t,session.answers).filter(r=>range.numbers.includes(r.n)),h={id:'result-'+Date.now(),testId:t.id,title:t.title+(session.scope==='part'?` · ${t.type==='listening'?'Part':'Passage'} ${session.entryPart+1}`:''),type:t.type,date:new Date().toISOString(),scope:session.scope,partIndex:session.entryPart,total:rows.length,graded:rows.filter(r=>r.correct!==null).length,correct:rows.filter(r=>r.correct===true).length,rows,auto};history.unshift(h);history=history.slice(0,100);store('ielts-history',history);localStorage.removeItem(sessionKey());reviewPart=session.entryPart||0;reviewMode='compare';showResult(h)};
function transcript(p,t){let text=p.transcriptText;if(text)return `<div class="transcript-text">${escapeHTML(text).replace(/\bQ\s?(\d{1,2})\b/g,'<span class="transcript-q">Q$1</span>')}</div>`;return '<div class="empty">当前源资料未提供可读的听力原文。</div>'}
showResult=function(h){activeResult=h;view='result';let t=allTests().find(t=>t.id===h.testId),graded=h.graded??h.total;if(h.scope==='part')reviewPart=h.partIndex;else if(!t?.parts[reviewPart])reviewPart=0;let rows=h.rows.filter(r=>r.n>(t?.parts.slice(0,reviewPart).reduce((n,p)=>n+p.questions.length,0)||0)&&r.n<=(t?.parts.slice(0,reviewPart+1).reduce((n,p)=>n+p.questions.length,0)||h.total));app.innerHTML=header()+`<main class="review-main"><section class="review-score"><div><span class="eyebrow">PRACTICE REVIEW</span><h2>${escapeHTML(h.title)}</h2><p>${new Date(h.date).toLocaleString('zh-CN')} ${h.auto?'· 时间结束自动交卷':''}</p></div><div class="review-total"><strong>${h.correct}</strong><span> / ${h.total}</span><small>${h.total-graded} 题待核对</small></div><div class="review-actions"><button class="primary" id="retry">重新练习</button><button class="secondary" id="export">导出记录</button><button class="secondary" data-home>返回题库</button></div></section><div class="review-toolbar"><div class="review-tabs"><button class="${reviewMode==='compare'?'active':''}" data-review="compare">批阅对照</button>${h.type==='listening'?`<button class="${reviewMode==='transcript'?'active':''}" data-review="transcript">听力原文</button>`:''}<button class="${reviewMode==='answers'?'active':''}" data-review="answers">答案一览</button></div><div>${t?.parts.map((p,i)=>h.scope==='part'&&i!==h.partIndex?'':`<button class="chip ${reviewPart===i?'active':''}" data-review-part="${i}">${h.type==='listening'?'Part':'Passage'} ${i+1}</button>`).join('')||''}</div></div>${reviewMode==='answers'?`<section class="card"><div class="answer-grid">${h.rows.map(r=>`<div class="answer-review-cell ${r.correct===true?'right':r.correct===false?'wrong':'pending'}"><b>${r.n}　${r.correct===true?'✓':r.correct===false?'✗':'待核对'}</b><span>我的答案：${escapeHTML(r.yours)||'未作答'}</span><span>参考答案：${escapeHTML(r.answer)||'源答案未确认'}</span>${r.correct===null?`<div><button class="chip" data-manual="${r.n}" data-value="yes">核对正确</button><button class="chip" data-manual="${r.n}" data-value="no">核对错误</button></div>`:''}</div>`).join('')}</div>${h.type!=='listening'&&(t?.keyImages?.length||t?.keyHtml)?`<details class="key-reference"><summary>原文件答案页</summary>${(t.keyImages||[]).map(u=>`<img class="key-image" src="${escapeHTML(u)}" alt="原文件答案">`).join('')}${t.keyHtml||''}</details>`:''}</section>`:t?`<div class="review-panes ${reviewMode==='transcript'?'transcript-only':''}">${reviewMode!=='transcript'?`<section class="review-task"><h3>${h.type==='listening'?'答题批阅':'阅读批阅'} · ${h.type==='listening'?'Part':'Passage'} ${reviewPart+1}</h3><p class="review-legend"><span>✓ 正确</span><span>✗ 错误（下方展示参考答案）</span></p>${nativePart(t,reviewPart,true,rows)}</section>`:''}<section class="review-transcript"><h3>${h.type==='listening'?'听力原文':'阅读原文'} · ${h.type==='listening'?'Part':'Passage'} ${reviewPart+1}</h3>${h.type==='listening'?transcript(t.parts[reviewPart],t):t.parts[reviewPart].readingHtml||`<div class="transcript-text">${escapeHTML(t.parts[reviewPart].passage||'')}</div>`}</section></div>`:'<div class="empty">未找到原题，请通过导出的记录查看作答。</div>'}</main>`;bindHeader();$('#retry').onclick=()=>t?start(t,h.scope==='part'?{part:h.partIndex}:{}):toast('未找到试卷');$('#export').onclick=()=>download('ielts-result.json',JSON.stringify(h,null,2));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{reviewMode=b.dataset.review;showResult(h)});document.querySelectorAll('[data-review-part]').forEach(b=>b.onclick=()=>{reviewPart=+b.dataset.reviewPart;showResult(h)});document.querySelectorAll('[data-manual]').forEach(b=>b.onclick=()=>{let row=h.rows.find(r=>r.n===+b.dataset.manual);row.correct=b.dataset.value==='yes';h.graded=h.rows.filter(r=>r.correct!==null).length;h.correct=h.rows.filter(r=>r.correct===true).length;store('ielts-history',history);showResult(h)})};
window.addEventListener('beforeunload',save); home();
